from pathlib import Path

path = Path('ClockTimer.js')
text = path.read_text()

old_new_segment = '''                    if (\n                        !firstSegment\n                    ) {\n                        this.#applyPreservedAttributes(\n                            segment,\n                            preservedAttributes\n                        );\n                    }\n'''
new_new_segment = '''                    if (\n                        !firstSegment\n                    ) {\n                        this.#applyPreservedAttributes(\n                            segment,\n                            preservedAttributes\n                        );\n\n                        this.#copyClockTimerRangeState(\n                            range,\n                            segment\n                        );\n                    }\n'''
if old_new_segment not in text:
    raise SystemExit('new split segment block not found')
text = text.replace(old_new_segment, new_new_segment, 1)

old_moved_segment = '''                        this.#applyPreservedAttributes(\n                            movedSegment,\n                            preservedAttributes\n                        );\n\n                        this.#setRangeTiming(\n'''
new_moved_segment = '''                        this.#applyPreservedAttributes(\n                            movedSegment,\n                            preservedAttributes\n                        );\n\n                        this.#copyClockTimerRangeState(\n                            range,\n                            movedSegment\n                        );\n\n                        this.#setRangeTiming(\n'''
if old_moved_segment not in text:
    raise SystemExit('moved split segment block not found')
text = text.replace(old_moved_segment, new_moved_segment, 1)

marker = '''        #shiftRangesAfter(\n            cutoff,\n            delta,\n            excludedRecord\n        ) {\n'''
replacement = '''        #shiftInsertedRangeElements(\n            cutoff,\n            delta,\n            excludedRecord\n        ) {\n            const excludedId =\n                excludedRecord?.id;\n\n            const ranges =\n                this.#getManagedTimeRanges()\n                    .filter(\n                        range =>\n                            range.clockTimerInserted !==\n                                undefined &&\n                            range.clockTimerInserted !==\n                                excludedId &&\n                            range.timeRangeExiting !==\n                                true\n                    );\n\n            for (const range of ranges) {\n                const start =\n                    Number(\n                        range.clockTimerStart\n                    );\n\n                const end =\n                    Number(\n                        range.clockTimerEnd\n                    );\n\n                if (\n                    !Number.isFinite(start) ||\n                    !Number.isFinite(end) ||\n                    end <= cutoff\n                ) {\n                    continue;\n                }\n\n                if (start >= cutoff) {\n                    this.#replaceRangeWithSegments(\n                        range,\n                        [[\n                            start + delta,\n                            end + delta\n                        ]]\n                    );\n\n                    continue;\n                }\n\n                this.#replaceRangeWithSegments(\n                    range,\n                    [\n                        [\n                            start,\n                            cutoff\n                        ],\n                        [\n                            cutoff + delta,\n                            end + delta\n                        ]\n                    ]\n                );\n            }\n        }\n\n        #syncOpenEndedRangeElements(\n            record,\n            effectiveEnd\n        ) {\n            const start =\n                this.#dateToTimelineTime(\n                    record.startDate\n                );\n\n            if (\n                !Number.isFinite(start) ||\n                !Number.isFinite(effectiveEnd) ||\n                effectiveEnd <= start\n            ) {\n                return;\n            }\n\n            const existing =\n                this.#getManagedTimeRanges()\n                    .filter(\n                        range =>\n                            range.clockTimerInserted ===\n                                record.id &&\n                            range.timeRangeExiting !==\n                                true\n                    )\n                    .sort(\n                        (a, b) =>\n                            Number(a.clockTimerStart) -\n                            Number(b.clockTimerStart)\n                    );\n\n            let cursor =\n                start;\n\n            let index =\n                0;\n\n            while (cursor < effectiveEnd) {\n                const ringIndex =\n                    this.#getRingIndex(\n                        cursor\n                    );\n\n                const ringEnd =\n                    this.#getRingStart(\n                        ringIndex\n                    ) +\n                    ClockTimer.#HOUR;\n\n                const segmentEnd =\n                    Math.min(\n                        effectiveEnd,\n                        ringEnd\n                    );\n\n                const ring =\n                    this.#ensureRing(\n                        ringIndex\n                    );\n\n                let range =\n                    existing[index];\n\n                if (!range) {\n                    range =\n                        this.#createTimeRange(\n                            record.type,\n                            cursor,\n                            segmentEnd,\n                            { dynamic: true }\n                        );\n\n                    delete range.clockTimerDynamic;\n\n                    range.clockTimerInserted =\n                        record.id;\n\n                    this.#applyOtherAttributes(\n                        range,\n                        record.otherAttributes\n                    );\n\n                    ring.appendChild(\n                        range\n                    );\n                }\n                else {\n                    if (\n                        range.parentElement !==\n                            ring\n                    ) {\n                        ring.appendChild(\n                            range\n                        );\n                    }\n\n                    this.#setRangeTiming(\n                        range,\n                        cursor,\n                        segmentEnd\n                    );\n                }\n\n                cursor =\n                    segmentEnd;\n\n                index++;\n            }\n\n            for (\n                ;\n                index < existing.length;\n                index++\n            ) {\n                const range =\n                    existing[index];\n\n                if (\n                    typeof range.removeAnimated ===\n                        'function'\n                ) {\n                    range.removeAnimated({\n                        collapseTo: 'start'\n                    });\n                }\n                else {\n                    range.remove();\n                }\n            }\n        }\n\n        #shiftRangesAfter(\n            cutoff,\n            delta,\n            excludedRecord,\n            renderInserted = true\n        ) {\n'''
if marker not in text:
    raise SystemExit('shiftRangesAfter marker not found')
text = text.replace(marker, replacement, 1)

old_shift_start = '''            this.#captureInsertedAttributes();\n\n            this.#shiftExistingTimeRanges(\n                cutoff,\n                delta\n            );\n\n            for (\n'''
new_shift_start = '''            this.#captureInsertedAttributes();\n\n            this.#shiftExistingTimeRanges(\n                cutoff,\n                delta\n            );\n\n            if (!renderInserted) {\n                this.#shiftInsertedRangeElements(\n                    cutoff,\n                    delta,\n                    excludedRecord\n                );\n            }\n\n            for (\n'''
if old_shift_start not in text:
    raise SystemExit('shift start block not found')
text = text.replace(old_shift_start, new_shift_start, 1)

old_render = '''            this.#rebuildOvertimeRangeMap();\n            this.#removeEmptyRings();\n            this.#renderAllInsertedRanges();\n\n            if (\n'''
new_render = '''            this.#rebuildOvertimeRangeMap();\n            this.#removeEmptyRings();\n\n            if (renderInserted) {\n                this.#renderAllInsertedRanges();\n            }\n\n            if (\n'''
if old_render not in text:
    raise SystemExit('shift render block not found')
text = text.replace(old_render, new_render, 1)

old_update = '''            this.#shiftRangesAfter(\n                previous,\n                delta,\n                record\n            );\n\n            this.#renderAllInsertedRanges();\n'''
new_update = '''            this.#shiftRangesAfter(\n                previous,\n                delta,\n                record,\n                false\n            );\n\n            this.#syncOpenEndedRangeElements(\n                record,\n                now\n            );\n\n            this.#refreshRingLayout(\n                this.#started\n                    ? this.#getCurrentTimelineTime()\n                    : now\n            );\n'''
if old_update not in text:
    raise SystemExit('open update block not found')
text = text.replace(old_update, new_update, 1)

path.write_text(text)
